// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "./AtlasXFactory.sol";
import "./AtlasXPair.sol";

interface IERC20Approve {
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/**
 * @title AtlasXRouter
 * @dev High-level DEX router for AtlasX — handles multi-hop swaps, add/remove liquidity
 */
contract AtlasXRouter {
    AtlasXFactory public immutable factory;

    constructor(address _factory) {
        factory = AtlasXFactory(_factory);
    }

    function addLiquidity(
        address tokenA,
        address tokenB,
        uint256 amountA,
        uint256 amountB
    ) external returns (uint256 lpTokens) {
        address pair = factory.getPair(tokenA, tokenB);
        if (pair == address(0)) {
            pair = factory.createPair(tokenA, tokenB);
        }
        IERC20Approve(tokenA).transferFrom(msg.sender, address(this), amountA);
        IERC20Approve(tokenB).transferFrom(msg.sender, address(this), amountB);
        IERC20Approve(tokenA).approve(pair, amountA);
        IERC20Approve(tokenB).approve(pair, amountB);
        lpTokens = AtlasXPair(pair).addLiquidity(amountA, amountB);
    }

    function swapExactTokensForTokens(
        address tokenIn,
        address tokenOut,
        uint256 amountIn
    ) external returns (uint256 amountOut) {
        address pair = factory.getPair(tokenIn, tokenOut);
        require(pair != address(0), "No pair");
        IERC20Approve(tokenIn).transferFrom(msg.sender, address(this), amountIn);
        IERC20Approve(tokenIn).approve(pair, amountIn);
        amountOut = AtlasXPair(pair).swap(tokenIn, amountIn);
    }

    function getAmountOut(
        address tokenIn,
        address tokenOut,
        uint256 amountIn
    ) external view returns (uint256) {
        address pair = factory.getPair(tokenIn, tokenOut);
        if (pair == address(0)) return 0;
        return AtlasXPair(pair).getAmountOut(tokenIn, amountIn);
    }
}

contracts/AtlasXToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/**
 * @title AtlasXToken
 * @dev Native platform token for the AtlasX DEX
 */
contract AtlasXToken {
    string public constant name = "AtlasX Token";
    string public constant symbol = "ATX";
    uint8 public constant decimals = 18;
    uint256 public constant INITIAL_SUPPLY = 1_000_000_000 * 10**18; // 1 billion

    address public owner;
    uint256 private _totalSupply;
    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner_, address indexed spender, uint256 value);
    event Mint(address indexed to, uint256 amount);
    event Burn(address indexed from, uint256 amount);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    constructor() {
        owner = msg.sender;
        _mint(msg.sender, INITIAL_SUPPLY);
    }

    function totalSupply() external view returns (uint256) { return _totalSupply; }

    function balanceOf(address account) external view returns (uint256) { return _balances[account]; }

    function allowance(address owner_, address spender) external view returns (uint256) {
        return _allowances[owner_][spender];
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        _allowances[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 allowed = _allowances[from][msg.sender];
        require(allowed >= amount, "Allowance exceeded");
        if (allowed != type(uint256).max) _allowances[from][msg.sender] -= amount;
        _transfer(from, to, amount);
        return true;
    }

    function mint(address to, uint256 amount) external onlyOwner {
        _mint(to, amount);
        emit Mint(to, amount);
    }

    function burn(uint256 amount) external {
        require(_balances[msg.sender] >= amount, "Insufficient balance");
        _balances[msg.sender] -= amount;
        _totalSupply -= amount;
        emit Transfer(msg.sender, address(0), amount);
        emit Burn(msg.sender, amount);
    }

    function _transfer(address from, address to, uint256 amount) internal {
        require(to != address(0), "Zero recipient");
        require(_balances[from] >= amount, "Insufficient balance");
        _balances[from] -= amount;
        _balances[to] += amount;
        emit Transfer(from, to, amount);
    }

    function _mint(address to, uint256 amount) internal {
        require(to != address(0), "Zero address");
        _totalSupply += amount;
        _balances[to] += amount;
        emit Transfer(address(0), to, amount);
    }
}

contracts/ERCAssetRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

contract AtlasXAssetRegistry {
    struct Asset {
        string symbol;
        string name;
        string metadataUri;
        address registrar;
        uint64 registeredAt;
    }

    Asset[] private assets;

    event AssetRegistered(
        uint256 indexed assetId,
        string symbol,
        string name,
        string metadataUri,
        address indexed registrar
    );

    function registerAsset(
        string calldata symbol,
        string calldata name,
        string calldata metadataUri
    ) external returns (uint256 assetId) {
        require(bytes(symbol).length > 0 && bytes(symbol).length <= 12, "Symbol must be 1-12 bytes");
        require(bytes(name).length > 0 && bytes(name).length <= 80, "Name must be 1-80 bytes");
        require(bytes(metadataUri).length <= 240, "Metadata URI is too long");

        assetId = assets.length;
        assets.push(
            Asset({
                symbol: symbol,
                name: name,
                metadataUri: metadataUri,
                registrar: msg.sender,
                registeredAt: uint64(block.timestamp)
            })
        );

        emit AssetRegistered(assetId, symbol, name, metadataUri, msg.sender);
    }

    function totalAssets() external view returns (uint256) {
        return assets.length;
    }

    function assetAt(uint256 assetId) external view returns (Asset memory) {
        require(assetId < assets.length, "Asset does not exist");
        return assets[assetId];
    }
}

