// SPDX-License-Identifier: MIT
// cspell:ignore XUSDT
pragma solidity ^0.8.28;

contract AtlasXUSDT1155 {
    uint256 public constant USDT_TOKEN_ID = 1;
    uint256 public constant INITIAL_SUPPLY = 50_000_000;
    uint256 public constant UNIT_VALUE_USD_6DP = 1_000_000;

    string public constant name = "ERC USDT TRC20 (ERC-1155 representation)";
    string public constant symbol = "USDT";
    string public constant networkName = "ERC";
    string public constant logoUri = "https://assets.coingecko.com/coins/images/325/small/Tether.png";

    address public immutable owner;
    string private metadataUri;
    uint256 private _totalSupply;
    mapping(address => mapping(uint256 => uint256)) private balances;
    mapping(address => mapping(address => bool)) private operatorApprovals;

    event TransferSingle(
        address indexed operator,
        address indexed from,
        address indexed to,
        uint256 id,
        uint256 value
    );
    event ApprovalForAll(address indexed account, address indexed operator, bool approved);
    event URI(string value, uint256 indexed id);

    constructor(string memory tokenMetadataUri) {
        owner = msg.sender;
        metadataUri = tokenMetadataUri;
        _mint(msg.sender, USDT_TOKEN_ID, INITIAL_SUPPLY);
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner");
        _;
    }

    function uri(uint256 id) external view returns (string memory) {
        require(id == USDT_TOKEN_ID, "Token does not exist");
        return metadataUri;
    }

    function totalSupply(uint256 id) external view returns (uint256) {
        require(id == USDT_TOKEN_ID, "Token does not exist");
        return _totalSupply;
    }

    function balanceOf(address account, uint256 id) external view returns (uint256) {
        require(account != address(0), "Zero account");
        require(id == USDT_TOKEN_ID, "Token does not exist");
        return balances[account][id];
    }

    function isApprovedForAll(address account, address operator) external view returns (bool) {
        return operatorApprovals[account][operator];
    }

    function setApprovalForAll(address operator, bool approved) external {
        require(operator != msg.sender, "Self approval");
        operatorApprovals[msg.sender][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    function safeTransferFrom(
        address from,
        address to,
        uint256 id,
        uint256 amount,
        bytes calldata
    ) external {
        require(to != address(0), "Zero recipient");
        require(from == msg.sender || operatorApprovals[from][msg.sender], "Not approved");
        require(id == USDT_TOKEN_ID, "Token does not exist");
        require(balances[from][id] >= amount, "Insufficient balance");

        balances[from][id] -= amount;
        balances[to][id] += amount;
        emit TransferSingle(msg.sender, from, to, id, amount);
    }

    function mint(address to, uint256 id, uint256 amount, bytes calldata) external onlyOwner {
        require(to != address(0), "Zero recipient");
        require(id == USDT_TOKEN_ID, "Token does not exist");
        _mint(to, id, amount);
    }

    function _mint(address to, uint256 id, uint256 amount) internal {
        balances[to][id] += amount;
        _totalSupply += amount;
        emit TransferSingle(msg.sender, address(0), to, id, amount);
    }
}

contracts/ITRC1155.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "./ITRC165.sol";

/// @title TRC-1155 Multi Token Standard — Core Interface
/// @dev Equivalent to ERC-1155 for TRON-compatible deployments.
///      interfaceID = 0xd9b67a26
interface ITRC1155 is ITRC165 {
    // -----------------------------------------------------------------------
    // Events
    // -----------------------------------------------------------------------

    /// @dev Emitted when `_operator` transfers a single token type.
    ///      `_from` == address(0) on mint; `_to` == address(0) on burn.
    event TransferSingle(
        address indexed _operator,
        address indexed _from,
        address indexed _to,
        uint256 _id,
        uint256 _value
    );

    /// @dev Emitted when `_operator` performs a batch transfer.
    ///      `_from` == address(0) on mint; `_to` == address(0) on burn.
    event TransferBatch(
        address indexed _operator,
        address indexed _from,
        address indexed _to,
        uint256[] _ids,
        uint256[] _values
    );

    /// @dev Emitted when an operator approval is toggled.
    event ApprovalForAll(
        address indexed _owner,
        address indexed _operator,
        bool _approved
    );

    /// @dev Emitted when the metadata URI for token `_id` is updated.
    event URI(string _value, uint256 indexed _id);

    // -----------------------------------------------------------------------
    // Functions
    // -----------------------------------------------------------------------

    /// @notice Authorize or revoke `_operator` to manage all tokens of the caller.
    function setApprovalForAll(address _operator, bool _approved) external;

    /// @notice Returns `true` if `_operator` is approved to manage all tokens of `_owner`.
    function isApprovedForAll(address _owner, address _operator) external view returns (bool);

    /// @notice Returns the balance of token `_id` held by `_owner`.
    function balanceOf(address _owner, uint256 _id) external view returns (uint256);

    /// @notice Returns balances for multiple (owner, id) pairs.
    ///         Both arrays must have the same length.
    function balanceOfBatch(
        address[] calldata _owners,
        uint256[] calldata _ids
    ) external view returns (uint256[] memory);

    /// @notice Safely transfers `_value` of token `_id` from `_from` to `_to`.
    ///         Calls `onERC1155Received` on `_to` if it is a contract.
    function safeTransferFrom(
        address _from,
        address _to,
        uint256 _id,
        uint256 _value,
        bytes calldata _data
    ) external;

    /// @notice Safely transfers multiple token types in a single transaction.
    ///         Calls `onERC1155BatchReceived` on `_to` if it is a contract.
    function safeBatchTransferFrom(
        address _from,
        address _to,
        uint256[] calldata _ids,
        uint256[] calldata _values,
        bytes calldata _data
    ) external;
}

